import{_ as t,o as a,c as r,a2 as i}from"./chunks/framework.BZO4qERu.js";const p=JSON.parse('{"title":"Service & credits","description":"","frontmatter":{},"headers":[],"relativePath":"online/credits.md","filePath":"online/credits.md","lastUpdated":1791997268000}'),s={name:"online/credits.md"};function o(n,e,d,l,c,h){return a(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="service-credits" tabindex="-1">Service &amp; credits <a class="header-anchor" href="#service-credits" aria-label="Permalink to &quot;Service &amp; credits&quot;">​</a></h1><p>PaperSeek Service is the default online mode: PaperSeek provides the models, and tasks spend your daily credits instead of your own provider accounts.</p><h2 id="use-paperseek-service" tabindex="-1">Use PaperSeek Service <a class="header-anchor" href="#use-paperseek-service" aria-label="Permalink to &quot;Use PaperSeek Service&quot;">​</a></h2><ol><li>Sign in. PaperSeek Service is the default mode.</li><li>Describe your question, choose a data source and a search budget.</li><li>Start the search. The form shows how many credits the task uses and how many are left today.</li></ol><p>Searching uses <strong>Auto</strong>, a built-in model chosen by PaperSeek. For reviews, choose <strong>Fast</strong> (the default, quicker) or <strong>Deep Research</strong> (more thorough, slower) as the writing model. Preliminary ranking is configured in the same place. Both settings live in <strong>Settings › Model service</strong>. Available sources are shown in the application.</p><h2 id="credits" tabindex="-1">Credits <a class="header-anchor" href="#credits" aria-label="Permalink to &quot;Credits&quot;">​</a></h2><p>During the public beta every account receives <strong>20 free credits a day</strong>. Only PaperSeek Service uses credits:</p><table tabindex="0"><thead><tr><th>Task</th><th>Credits</th></tr></thead><tbody><tr><td>Search</td><td>1</td></tr><tr><td>Bibliometric analysis</td><td>1</td></tr><tr><td>Review</td><td>5 for the whole review</td></tr></tbody></table><p>Credits are deducted when you submit a task. A review is charged once, by its first writing task; generating the outline again, writing, and rewriting sections of the same review are free. If a task fails or is cancelled, its credits are returned; a task that completes with warnings is not refunded.</p><p>Your remaining credits appear in the sidebar and in <strong>Settings › User</strong>, together with the daily refill time.</p><h2 id="ask-for-a-larger-allowance" tabindex="-1">Ask for a larger allowance <a class="header-anchor" href="#ask-for-a-larger-allowance" aria-label="Permalink to &quot;Ask for a larger allowance&quot;">​</a></h2><p>To ask for a larger allowance during the public beta, email <a href="mailto:support@paperseek.app" target="_blank" rel="noreferrer">support@paperseek.app</a> with your account ID (copy it in <strong>Settings › User</strong>), your institution, and how you use PaperSeek.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./byok">Your own keys</a> — run tasks without credits.</li><li><a href="./account">Your account</a> — credits display and account settings.</li></ul>',14)])])}const g=t(s,[["render",o]]);export{p as __pageData,g as default};
